package com.minimarket.cliente.service; import com.minimarket.cliente.dto.*; import com.minimarket.cliente.entity.*; import com.minimarket.cliente.repository.*; import com.minimarket.common.exception.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class ClienteServiceImpl implements ClienteService{private final ClienteRepository r;private final TipoDocumentoIdentidadRepository t;public Page<ClienteResponseDTO> listar(String q,Pageable p){return (q==null||q.isBlank()?r.findByActivoTrue(p):r.findByNombreRazonSocialContainingIgnoreCaseAndActivoTrue(q,p)).map(this::d);}public ClienteResponseDTO obtener(Long id){return d(f(id));}public ClienteResponseDTO porDocumento(String n){return r.findFirstByNumeroDocumentoAndActivoTrue(n).map(this::d).orElseThrow(()->new ResourceNotFoundException("Cliente no encontrado: "+n));}@Transactional public ClienteResponseDTO crear(ClienteRequestDTO x){var td=t.findById(x.tipoDocumentoId()).orElseThrow(()->ResourceNotFoundException.of("TipoDocumento",x.tipoDocumentoId()));if(r.findByTipoDocumentoIdAndNumeroDocumento(x.tipoDocumentoId(),x.numeroDocumento().trim()).isPresent())throw new BusinessException("Documento de cliente ya registrado");return d(r.save(Cliente.builder().tipoDocumento(td).numeroDocumento(x.numeroDocumento().trim()).nombreRazonSocial(x.nombreRazonSocial().trim()).nombreComercial(x.nombreComercial()).direccion(x.direccion()).telefono(x.telefono()).email(x.email()).activo(true).build()));}@Transactional public ClienteResponseDTO actualizar(Long id,ClienteRequestDTO x){Cliente c=f(id);var td=t.findById(x.tipoDocumentoId()).orElseThrow(()->ResourceNotFoundException.of("TipoDocumento",x.tipoDocumentoId()));r.findByTipoDocumentoIdAndNumeroDocumento(x.tipoDocumentoId(),x.numeroDocumento().trim()).filter(a->!a.getId().equals(id)).ifPresent(a->{throw new BusinessException("Documento de cliente ya registrado");});c.setTipoDocumento(td);c.setNumeroDocumento(x.numeroDocumento().trim());c.setNombreRazonSocial(x.nombreRazonSocial().trim());c.setNombreComercial(x.nombreComercial());c.setDireccion(x.direccion());c.setTelefono(x.telefono());c.setEmail(x.email());return d(c);}@Transactional public void desactivar(Long id){f(id).setActivo(false);}private Cliente f(Long id){return r.findById(id).orElseThrow(()->ResourceNotFoundException.of("Cliente",id));}private ClienteResponseDTO d(Cliente c){return new ClienteResponseDTO(c.getId(),c.getTipoDocumento().getId(),c.getTipoDocumento().getCodigo(),c.getNumeroDocumento(),c.getNombreRazonSocial(),c.getNombreComercial(),c.getDireccion(),c.getTelefono(),c.getEmail(),c.getActivo(),c.getCreatedAt());}}